INSERT OR REPLACE INTO District_Adjacencies (DistrictType,YieldChangeId) VALUES
('DISTRICT_INDUSTRIAL_ZONE',		'SFDH100_CORPORATION_PRODUCTION'),
('DISTRICT_INDUSTRIAL_ZONE',		'SFDH100_INDUSTRY_PRODUCTION'),
('DISTRICT_HARBOR',					'SFDH100_CORPORATION_GOLD'),
('DISTRICT_HARBOR',					'SFDH100_INDUSTRY_GOLD'),
('DISTRICT_COMMERCIAL_HUB',			'SFDH100_CORPORATION_GOLD'),
('DISTRICT_COMMERCIAL_HUB',			'SFDH100_INDUSTRY_GOLD');
INSERT OR REPLACE INTO District_Adjacencies (DistrictType,YieldChangeId)
SELECT			DistrictType,			'SFDH100_CORPORATION_PRODUCTION'	FROM	Districts	WHERE	DistrictType IS 'DISTRICT_INDUSTRIAL_ZONE' 	OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_INDUSTRIAL_ZONE')
UNION SELECT	DistrictType,			'SFDH100_INDUSTRY_PRODUCTION'		FROM	Districts	WHERE	DistrictType IS 'DISTRICT_INDUSTRIAL_ZONE' 	OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_INDUSTRIAL_ZONE')
UNION SELECT	DistrictType,			'SFDH100_CORPORATION_GOLD'			FROM	Districts	WHERE	DistrictType IS 'DISTRICT_HARBOR' 			OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_HARBOR')
UNION SELECT	DistrictType,			'SFDH100_INDUSTRY_GOLD'				FROM	Districts	WHERE	DistrictType IS 'DISTRICT_HARBOR' 			OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_HARBOR')
UNION SELECT	DistrictType,			'SFDH100_CORPORATION_GOLD'			FROM	Districts	WHERE	DistrictType IS 'DISTRICT_COMMERCIAL_HUB' 	OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_COMMERCIAL_HUB')
UNION SELECT	DistrictType,			'SFDH100_INDUSTRY_GOLD'				FROM	Districts	WHERE	DistrictType IS 'DISTRICT_COMMERCIAL_HUB' 	OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_COMMERCIAL_HUB');